SELECT




        a.status = #{status}


        AND a.category_id = #{categoryId}


        AND EXISTS (
            SELECT 1 FROM article_tag at2
            WHERE at2.article_id = a.id AND at2.tag_id = #{tagId}
        )


        AND a.title LIKE CONCAT('%', #{keyword}, '%')


ORDER BY a.created_at DESC, a.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM article a


        a.status = #{status}


        AND a.category_id = #{categoryId}


        AND EXISTS (
            SELECT 1 FROM article_tag at3
            WHERE at3.article_id = a.id AND at3.tag_id = #{tagId}
        )


        AND a.title LIKE CONCAT('%', #{keyword}, '%')
